        public static Geometry For(TipCategory category) => category switch
        {
            TipCategory.Exercise => Walking,
            TipCategory.Eyes => Eye,
            TipCategory.Hydration => Drop,
            TipCategory.Sedentary => HeartPulse,
            _ => Wind
        };

        /// <summary>SVG 默认按非零规则填充，WPF 默认奇偶规则，前缀 F1 切成非零规则</summary>
        private static Geometry Parse(string data)
        {
            var geometry = Geometry.Parse("F1 " + data);
            geometry.Freeze();
            return geometry;
        }
